import React, { useEffect, useState } from "react";
import { Zap } from "lucide-react";

const WorkerSplash = ({ onComplete }) => {
  const [isZooming, setIsZooming] = useState(false);

  useEffect(() => {
    // Start the zoom-into-the-screen effect after 2 seconds
    const timer = setTimeout(() => {
      setIsZooming(true);
    }, 2200);

    const finish = setTimeout(onComplete, 3500);

    return () => {
      clearTimeout(timer);
      clearTimeout(finish);
    };
  }, [onComplete]);

  return (
    <div className="h-screen bg-black flex items-center justify-center overflow-hidden relative">
      {/* Background Tactical Grid */}
      <div className="absolute inset-0 opacity-10 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]" />

      {/* Vertical Scanlines (Netflix Vibe) */}
      <div className="absolute inset-0 flex justify-around opacity-20">
        {[...Array(5)].map((_, i) => (
          <div key={i} className="w-[1px] bg-[#CAD23C] animate-line-glow" style={{ animationDelay: `${i * 0.2}s` }} />
        ))}
      </div>

      {/* The Central "N" Style Logo */}
      <div className={`relative transition-all duration-700 ${isZooming ? "animate-netflix-zoom" : "scale-100"}`}>
        {/* Glow effect */}
        <div className="absolute inset-0 bg-[#CAD23C] blur-[60px] opacity-30 animate-pulse" />

        {/* The Heavy Icon */}
        <div className="relative bg-[#47510B] p-12 rounded-2xl border-b-[12px] border-r-[12px] border-black shadow-[0_0_50px_rgba(202,210,60,0.4)]">
          <Zap size={100} className="text-[#CAD23C] fill-[#CAD23C] drop-shadow-2xl" strokeWidth={3} />

          {/* Text inside the zoom block */}
          <div className="absolute bottom-2 right-4">
             <span className="text-white font-black text-[10px] italic opacity-50">T2T_OS</span>
          </div>
        </div>
      </div>

      {/* Bottom Loading Text */}
      {!isZooming && (
        <div className="absolute bottom-20 text-center animate-in fade-in slide-in-from-bottom-4 duration-1000">
          <h2 className="text-[#CAD23C] font-black italic tracking-[0.5em] text-xs uppercase opacity-80 mb-4">
            Establishing_Secure_Link
          </h2>
          <div className="w-40 h-[2px] bg-white/10 mx-auto overflow-hidden">
            <div className="h-full bg-[#CAD23C] animate-progress" />
          </div>
        </div>
      )}

      {/* Screen Glitch Overlay */}
      <div className="absolute inset-0 pointer-events-none bg-gradient-to-t from-black via-transparent to-black opacity-60" />
    </div>
  );
};

export default WorkerSplash;
